'use strict';
// Adapted from the user's previous prototype in backup; no external assets.
(()=>{
function bind(dialog){
const canvas=document.getElementById('friendsWalk'),ctx=canvas.getContext('2d'),play=document.getElementById('walkPlay'),replay=document.getElementById('walkReplay'),status=document.getElementById('walkStatus');
const colors=['#ff655f','#ffac4e','#ffe36a','#75ef9b','#62d1ff','#9290ff','#d188ff'],names=['紅','橙','黃','綠','藍','靛','紫'];
const duration=12500,reduced=matchMedia('(prefers-reduced-motion: reduce)');let elapsed=reduced.matches?duration:0,playing=!reduced.matches,inView=false,last=0,frame=0;
function stroke(points,color,width=2){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function position(i,time){const start=260-i*34,join=3000+i*400,finish=10300+i*320;
if(time<join)return {x:start+(320-start)*Math.min(1,time/join),y:115,done:false};
const t=Math.min(1,(time-join)/(finish-join));return {x:320+330*t,y:115+(45+i*74)*t,done:t===1};}
function render(){ctx.clearRect(0,0,720,660);ctx.fillStyle='#0B1D4A';ctx.fillRect(0,0,720,660);
ctx.font='22px Microsoft JhengHei,sans-serif';ctx.fillStyle='#d5e7ed';ctx.textAlign='left';ctx.fillText('先排隊走',22,31);ctx.fillText('穿過斜玻璃線',263,31);ctx.fillText('轉彎後分開',565,31);
stroke([[300,48],[470,620]],'#8edbe7',4);ctx.save();ctx.setLineDash([4,6]);stroke([[24,115],[320,115]],'#456978',1);ctx.restore();
for(let i=6;i>=0;i--){const p=position(i,elapsed),height=70-i*5,walk=p.done||!playing?0:Math.sin(elapsed/110+i)*5;ctx.save();ctx.globalAlpha=.38;if(elapsed>3000+i*400)stroke([[320,115],[p.x,p.y]],colors[i],2);ctx.restore();
ctx.fillStyle=colors[i];ctx.beginPath();ctx.arc(p.x,p.y-height,8,0,Math.PI*2);ctx.fill();ctx.lineCap='round';const hip=p.y-height*.37,shoulder=p.y-height+12;stroke([[p.x,shoulder],[p.x,hip]],colors[i],4);stroke([[p.x-10,shoulder+10+walk*.5],[p.x,shoulder+5],[p.x+10,shoulder+10-walk*.5]],colors[i],4);stroke([[p.x-7-walk, p.y],[p.x,hip],[p.x+7+walk,p.y]],colors[i],4);
if(p.done){ctx.font='22px Microsoft JhengHei,sans-serif';ctx.textAlign='left';ctx.fillText(names[i],p.x+19,p.y-8);}}
ctx.fillStyle='#b8d2dd';ctx.font='18px Microsoft JhengHei,sans-serif';ctx.textAlign='left';ctx.fillText('身高代表波長長短；路徑與轉彎幅度為比喻示意。',22,644);
status.textContent=elapsed>=duration?'七個小夥伴分開了：紅色轉得少，紫色轉得多。':elapsed<3000?'七個小夥伴排成一列，朝玻璃前進。':'通過玻璃後，各自轉不同的角度，隊伍慢慢散開。';play.textContent=elapsed>=duration?'播放一次':playing?'暫停':'繼續播放';}
function tick(now){frame=0;if(!playing||!inView||!dialog.open)return;elapsed=Math.min(duration,elapsed+(last?now-last:0));last=now;if(elapsed===duration)playing=false;render();if(playing)frame=requestAnimationFrame(tick);}
function schedule(){last=0;if(!frame&&playing&&inView&&dialog.open)frame=requestAnimationFrame(tick);}
play.onclick=()=>{if(elapsed>=duration){elapsed=0;playing=true;}else playing=!playing;render();schedule();};replay.onclick=()=>{elapsed=0;playing=true;render();schedule();};
const visibility=new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;if(inView)schedule();else last=0;},{threshold:.4});visibility.observe(canvas);
const changes=new MutationObserver(()=>{if(dialog.open){elapsed=reduced.matches?duration:0;playing=!reduced.matches;render();schedule();}else{if(frame)cancelAnimationFrame(frame);frame=0;last=0;}});changes.observe(dialog,{attributes:true,attributeFilter:['open']});
dialog.addEventListener('close',()=>{visibility.disconnect();changes.disconnect();cancelAnimationFrame(frame);},{once:true});
render();
}
window.RainbowGuide={html:"<p class=\"eyebrow\">你發現陽光裡的祕密了！</p><h2 id=\"rainbowDialogTitle\">白色陽光裡，藏著好多顏色</h2><p>玻璃沒有幫陽光上色。紅、橙、黃、綠、藍、靛、紫，本來就一起藏在白光裡！經過玻璃時，各種色光轉彎的程度不同，分開後就看得見了。這叫做「<strong>色散</strong>」。</p><h3>想像七個不同身高的小夥伴</h3><div id=\"colorFriends\" class=\"colorFriends\" role=\"img\" aria-label=\"七個小人依序由高到矮：紅、橙、黃、綠、藍、靛、紫。紅光波長較長，紫光波長較短。\"><div><svg viewBox=\"0 0 60 130\" aria-hidden=\"true\"><g stroke=\"#ff6464\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"#ff6464\"><circle cx=\"30\" cy=\"22\" r=\"8\"/><path d=\"M30 36V84M14 64L30 46 46 64M16 115L30 84 44 115\" fill=\"none\"/></g></svg><span>紅</span></div><div><svg viewBox=\"0 0 60 130\" aria-hidden=\"true\"><g stroke=\"#ffad4c\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"#ffad4c\"><circle cx=\"30\" cy=\"27\" r=\"8\"/><path d=\"M30 41V84M14 64L30 51 46 64M16 115L30 84 44 115\" fill=\"none\"/></g></svg><span>橙</span></div><div><svg viewBox=\"0 0 60 130\" aria-hidden=\"true\"><g stroke=\"#ffe568\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"#ffe568\"><circle cx=\"30\" cy=\"32\" r=\"8\"/><path d=\"M30 46V84M14 64L30 56 46 64M16 115L30 84 44 115\" fill=\"none\"/></g></svg><span>黃</span></div><div><svg viewBox=\"0 0 60 130\" aria-hidden=\"true\"><g stroke=\"#80ec9c\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"#80ec9c\"><circle cx=\"30\" cy=\"37\" r=\"8\"/><path d=\"M30 51V84M14 64L30 61 46 64M16 115L30 84 44 115\" fill=\"none\"/></g></svg><span>綠</span></div><div><svg viewBox=\"0 0 60 130\" aria-hidden=\"true\"><g stroke=\"#65c8ff\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"#65c8ff\"><circle cx=\"30\" cy=\"42\" r=\"8\"/><path d=\"M30 56V84M14 64L30 66 46 64M16 115L30 84 44 115\" fill=\"none\"/></g></svg><span>藍</span></div><div><svg viewBox=\"0 0 60 130\" aria-hidden=\"true\"><g stroke=\"#a89aff\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"#a89aff\"><circle cx=\"30\" cy=\"47\" r=\"8\"/><path d=\"M30 61V84M14 64L30 71 46 64M16 115L30 84 44 115\" fill=\"none\"/></g></svg><span>靛</span></div><div><svg viewBox=\"0 0 60 130\" aria-hidden=\"true\"><g stroke=\"#de9fff\" stroke-width=\"6\" stroke-linecap=\"round\" fill=\"#de9fff\"><circle cx=\"30\" cy=\"52\" r=\"8\"/><path d=\"M30 66V84M14 64L30 76 46 64M16 115L30 84 44 115\" fill=\"none\"/></g></svg><span>紫</span></div></div><div class=\"friendCaptions\"><span>紅光：波長較長<br>在此玻璃中，偏折較少</span><span>紫光：波長較短<br>在此玻璃中，偏折較多</span></div><p>用身高代表「波長」：紅光波長較長，紫光波長較短。在這類玻璃中，紫光通常比紅光偏折得更多。<strong>小夥伴只是幫助記憶的比喻，光不是因為身高或靈活度才轉彎。</strong></p><section class=\"walkSection\" aria-labelledby=\"walkTitle\"><h3 id=\"walkTitle\">一起走進玻璃，看看誰轉得多</h3><p class=\"walkIntro\">先看七個小夥伴排隊走，再看通過玻璃後，誰往哪裡走。</p><div class=\"walkCanvasWrap\"><canvas id=\"friendsWalk\" width=\"720\" height=\"660\" aria-label=\"七個不同身高的小人先排成一列走向斜玻璃線，通過後，紅色轉彎較少，紫色轉彎較多，最後在右側分開。\"></canvas></div><div class=\"walkToolbar\"><p id=\"walkStatus\" role=\"status\"></p><div><button id=\"walkPlay\">暫停</button><button id=\"walkReplay\">重新看一次</button></div></div></section><p class=\"walkConclusion\">當隊伍經過玻璃時，因為每個人轉的角度不一樣多，隊伍就散開了！變成一道道彩色的光！</p><h3>為什麼換玻璃，結果不一樣？</h3><figure class=\"glassComparison\"><svg viewBox=\"0 0 660 480\" role=\"img\" aria-labelledby=\"compareTitle compareDesc\"><title id=\"compareTitle\">方形與三角形玻璃出光比較</title><desc id=\"compareDesc\">上圖方形玻璃左右面平行，出光位置以虛線框圈出，不同顏色朝相同方向走。下圖三角形玻璃兩側方向不同，出光位置以虛線框圈出，不同顏色朝不同方向散開。色彩間距加強示意。</desc><rect width=\"660\" height=\"480\" rx=\"14\" fill=\"#0B1D4A\"/><g font-family=\"Microsoft JhengHei,sans-serif\" font-size=\"20\" fill=\"#e6f4f8\"><text x=\"22\" y=\"33\">方形玻璃</text><text x=\"22\" y=\"260\">三角形玻璃</text></g><path d=\"M170 56H290V180H170Z M220 285 140 441H300Z\" fill=\"#64c9d32d\" stroke=\"#8bdded\" stroke-width=\"2\"/><path d=\"M36 80 170 112\" stroke=\"white\" stroke-width=\"5\" fill=\"none\"/><path d=\"M170 112 290 130\" stroke=\"white\" stroke-width=\"4\"/><g fill=\"none\" stroke-width=\"2.5\"><path d=\"M290 125 470 168\" stroke=\"#ff655f\"/><path d=\"M290 127 470 170\" stroke=\"#ffac4e\"/><path d=\"M290 129 470 172\" stroke=\"#ffe36a\"/><path d=\"M290 131 470 174\" stroke=\"#75ef9b\"/><path d=\"M290 133 470 176\" stroke=\"#62d1ff\"/><path d=\"M290 135 470 178\" stroke=\"#9290ff\"/><path d=\"M290 137 470 180\" stroke=\"#d188ff\"/></g><path d=\"M36 341H191L257 358\" stroke=\"white\" stroke-width=\"4\" fill=\"none\"/><g fill=\"none\" stroke-width=\"2.5\"><path d=\"M257 358 470 383\" stroke=\"#ff655f\"/><path d=\"M257 358 470 395\" stroke=\"#ffac4e\"/><path d=\"M257 358 470 407\" stroke=\"#ffe36a\"/><path d=\"M257 358 470 419\" stroke=\"#75ef9b\"/><path d=\"M257 358 470 431\" stroke=\"#62d1ff\"/><path d=\"M257 358 470 443\" stroke=\"#9290ff\"/><path d=\"M257 358 470 455\" stroke=\"#d188ff\"/></g><g fill=\"none\" stroke=\"#ffe39a\" stroke-width=\"2\" stroke-dasharray=\"6 5\"><rect x=\"280\" y=\"102\" width=\"203\" height=\"94\" rx=\"10\"/><rect x=\"250\" y=\"342\" width=\"233\" height=\"122\" rx=\"10\"/></g><g fill=\"#ffe39a\" font-family=\"Microsoft JhengHei,sans-serif\" font-size=\"18\"><text x=\"495\" y=\"130\">方向相同，</text><text x=\"495\" y=\"159\">隊伍沒有展開，</text><text x=\"495\" y=\"188\">色散不明顯</text><text x=\"495\" y=\"366\">方向不同，</text><text x=\"495\" y=\"395\">隊伍越走越開，</text><text x=\"495\" y=\"424\">色散更明顯</text></g><path d=\"M22 226H638\" stroke=\"#426271\"/></svg><figcaption>看黃色虛線框：比較光離開玻璃後的方向。光路與顏色間距為加強示意。</figcaption></figure><p>三角形玻璃兩邊的方向不同，容易讓色光往不同方向散開。方形玻璃也會讓不同顏色稍微分開；如果從互相平行的兩面進出，出來的光會朝相同方向走，比較不容易看見展開的彩色光帶。</p><section class=\"continuousColors\" aria-labelledby=\"continuousTitle\"><h3 id=\"continuousTitle\">彩虹，遠遠不只有七種顏色</h3><div class=\"spectrumGradient\" role=\"img\" aria-label=\"從紅、橙、黃、綠、藍到紫，平滑連續變化的彩虹漸層，沒有七條分界線。\"></div><p><strong>彩虹是一串連續、細緻的顏色變化，絕對不只有七個顏色。</strong>紅與橙之間、藍與紫之間，都還有許多漸漸變化的顏色，沒有清楚的分隔線。</p><p>我們把它分成「七色」，只是為了方便觀察與描述。剛剛的七個小夥伴，是從這一整串色彩中選出的代表喔！</p></section><p class=\"feedback\">這裡找到的是像彩虹一樣的「光譜」。天空中的彩虹還需要陽光在水滴內折射、反射，再折射出來；三稜鏡活動只示範色散這個部分。</p>",bind};
})();

